data:
@IsCoveringMap.monodromyFunctor.{u_1,
    u_2} : {E : Type u_1} →
  {X : Type u_2} →
    [inst : TopologicalSpace.{u_1} E] →
      [inst_1 : TopologicalSpace.{u_2} X] →
        {p : E → X} →
          @IsCoveringMap.{u_1, u_2} E X inst inst_1 p →
            @CategoryTheory.Functor.{u_2, u_1, u_2, u_1 + 1} (FundamentalGroupoid.{u_2} X)
              (@CategoryTheory.Groupoid.toCategory.{u_2, u_2} (FundamentalGroupoid.{u_2} X)
                (@FundamentalGroupoid.instGroupoid.{u_2} X inst_1))
              (Type u_1) CategoryTheory.types.{u_1}

@IsCoveringMap.monodromy_bijective.{u_1,
    u_2} : ∀ {E : Type u_1} {X : Type u_2} [inst : TopologicalSpace.{u_1} E] [inst_1 : TopologicalSpace.{u_2} X]
  {p : E → X} (cov : @IsCoveringMap.{u_1, u_2} E X inst inst_1 p) {x y : X}
  (γ : @Path.Homotopic.Quotient.{u_2} X inst_1 x y),
  @Function.Bijective.{u_1 + 1, u_1 + 1}
    (@Set.Elem.{u_1} E
      (@Set.preimage.{u_1, u_2} E X p (@singleton.{u_2, u_2} X (Set.{u_2} X) (@Set.instSingletonSet.{u_2} X) x)))
    (@Set.Elem.{u_1} E
      (@Set.preimage.{u_1, u_2} E X p (@singleton.{u_2, u_2} X (Set.{u_2} X) (@Set.instSingletonSet.{u_2} X) y)))
    (@IsCoveringMap.monodromy.{u_1, u_2} E X inst inst_1 p cov x y γ)
